-- Migration: Year 2 - Hematology Pathology MCQs Part 6 (201-240)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Hematology Pathology', 'hematology-pathology', 3, 2, 61)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- MULTIPLE MYELOMA (201-218)
    (v_topic_id, 'Multiple Myeloma (MM) is a plasma cell neoplasm. What is the cell of origin?', '["Immature B-lymphocyte (pre-B cell)", "Post-germinal center, class-switched plasma cell that has undergone somatic hypermutation and class switching", "Naive B-cell", "T-follicular helper cell"]', 1, 'MM arises from post-germinal center, long-lived plasma cells that have already undergone antigen selection, somatic hypermutation, and class switching. They home to and proliferate in the bone marrow. MM is essentially a clonal expansion of mature plasma cells secreting a monoclonal immunoglobulin (M-protein).'),
    (v_topic_id, 'The classic CRAB criteria define end-organ damage in Multiple Myeloma. What does CRAB stand for?', '["Cough, Renal failure, Anemia, Bone pain", "hypCalcemia, Renal failure, Anemia, Bone lesions (lytic)", "Coagulopathy, Rash, Azotemia, Bleeding", "Cytopenias, Reticulocytosis, Acidosis, Bone marrow failure"]', 1, 'CRAB: hyperCalcemia (from osteoclast activation), Renal failure (from light chain cast nephropathy), Anemia (from marrow replacement and cytokine suppression of erythropoiesis), Bone lytic lesions (punched-out lesions from osteoclast activation without osteoblast response). Any CRAB criterion = treat immediately.'),
    (v_topic_id, 'The M-protein (monoclonal protein) in myeloma is detected by which test?', '["CBC with differential", "Serum Protein Electrophoresis (SPEP) showing a narrow spike (M-spike) in the gamma region, confirmed by immunofixation electrophoresis", "CT scan of the chest", "Bone marrow biopsy alone"]', 1, 'SPEP shows an M-spike (monoclonal immunoglobulin) in the gamma region. Immunofixation identifies the Ig class (IgG most common in MM, then IgA). Serum free light chain assay detects free kappa or lambda chains. 24-hour urine for Bence Jones protein (free light chains).'),
    (v_topic_id, 'Bence Jones proteins in the urine of a myeloma patient represent?', '["Entire IgG molecules spilled into the urine", "Free immunoglobulin light chains (kappa or lambda) that pass through the glomerular filter and are excreted in urine", "Albumin from nephrotic syndrome", "Beta-2 microglobulin only"]', 1, 'Light chains (kappa or lambda) are small enough to be filtered by the glomerulus. In myeloma, overproduction overwhelms tubular reabsorption capacity. Light chains form casts in tubules, causing cast nephropathy (myeloma kidney). Bence Jones proteins classically precipitate at 40-60 degrees C and dissolve on boiling.'),
    (v_topic_id, 'The bone lesions in Multiple Myeloma are lytic (punched-out). Why is the alkaline phosphatase typically NORMAL in myeloma (unlike metastatic bone disease)?', '["ALP is consumed by the M-protein", "Myeloma cells activate osteoclasts (via RANK-L) but SUPPRESS osteoblasts (via DKK-1 and sclerostin), so there is no new bone formation and no ALP rise", "Myeloma cells absorb ALP from bone", "The kidneys excrete ALP in myeloma"]', 1, 'Myeloma produces factors (DKK-1 = Dickkopf-1, sclerostin) that inhibit Wnt signaling and suppress osteoblast activity. Without osteoblast bone formation, there is no ALP rise. Contrast with prostate cancer bone metastases (osteoblastic → elevated ALP).'),
    (v_topic_id, 'A skeletal survey (X-rays) in myeloma shows punched-out lytic lesions. Why is a bone scan (nuclear medicine) typically NEGATIVE in myeloma?', '["The M-protein blocks the radiotracer", "Bone scan detects osteoblast activity (new bone formation). Myeloma suppresses osteoblasts, so there is no new bone to detect despite lytic destruction", "Myeloma lesions are too small for bone scan", "Bone scans are only used for osteosarcoma"]', 1, 'Radionuclide bone scan uses technetium-99m bisphosphonate, which is taken up by metabolically active osteoblasts laying down new bone. In myeloma, osteoblasts are suppressed → no new bone formation → no scan uptake. Whole-body MRI and PET/CT are preferred for myeloma staging.'),
    (v_topic_id, 'The rouleaux formation seen on peripheral blood smear in myeloma is caused by?', '["Autoantibodies against RBCs causing clumping", "High serum protein (M-protein) coats RBCs, reducing their negative charge (zeta potential) and allowing them to stack like coins", "Hyperviscosity causing RBC aggregation", "Cryoglobulins causing cold agglutination"]', 1, 'The M-protein (monoclonal immunoglobulin) coats RBC surfaces, neutralizing their normal negative charge repulsion. RBCs then aggregate in linear stacks (rouleaux = stacked coins appearance). Also causes elevated ESR (sedimentation rate accelerated by the protein coating RBCs).'),
    (v_topic_id, 'Hypercalcemia in Multiple Myeloma occurs by which mechanism?', '["Myeloma cells directly deposit calcium in bones", "Myeloma cells produce RANK-L and other osteoclast-activating factors (IL-1, IL-6, MIP-1alpha) that stimulate osteoclasts to resorb bone, releasing calcium into the bloodstream", "PTH-related protein (PTHrP) secretion", "Vitamin D overactivation"]', 1, 'Myeloma cells (and stromal cells in the bone marrow niche) produce RANK-L (receptor activator of NF-kB ligand), IL-1, IL-6, and MIP-1alpha, all of which activate osteoclasts. Massive bone resorption → hypercalcemia. Hypercalcemia symptoms: bones (pain), stones (renal), groans (GI), psychic moans (neuropsych).'),
    (v_topic_id, 'Renal failure in Multiple Myeloma is most commonly caused by?', '["Glomerulonephritis from immune complex deposition", "Cast nephropathy (myeloma kidney): free light chains precipitate in tubular lumen forming obstructing casts, causing tubular damage and interstitial nephritis", "Amyloid deposition in glomeruli only", "NSAIDs used for bone pain"]', 1, 'Light chain cast nephropathy (myeloma kidney): free light chains (especially lambda more than kappa) bind Tamm-Horsfall protein in tubules and precipitate as eosinophilic, fractured-appearing casts surrounded by giant cells. This tubular obstruction causes progressive renal failure.'),
    (v_topic_id, 'Which immunoglobulin isotype is the MOST common M-protein in Multiple Myeloma?', '["IgM (most common)", "IgG (most common, ~50%), followed by IgA (~20%), then light chain only, then IgD (rare)", "IgA (most common)", "IgE (most common)"]', 1, 'IgG MM = ~50%, IgA MM = ~20%, light chain only (BJP myeloma) = ~15-20%, IgD = rare, IgE = extremely rare, non-secretory = ~1-2%. Note: IgM monoclonal gammopathy is more typical of Waldenstrom macroglobulinemia (lymphoplasmacytic lymphoma), not myeloma.'),
    (v_topic_id, 'Monoclonal Gammopathy of Undetermined Significance (MGUS) is a precursor state to myeloma. What distinguishes MGUS from smoldering myeloma and overt MM?', '["MGUS has lytic bone lesions", "MGUS: M-protein <3 g/dL, <10% plasma cells in marrow, NO CRAB criteria. It does not require treatment but needs monitoring (1% per year risk of progression to MM)", "MGUS has Bence Jones proteinuria", "MGUS requires chemotherapy immediately"]', 1, 'MGUS is defined by the absence of end-organ damage (no CRAB) and low disease burden (<10% marrow plasma cells, M-protein <3 g/dL). It requires watchful waiting only. Smoldering MM = higher burden but still no CRAB. Overt MM = CRAB present, requires treatment.'),
    (v_topic_id, 'The bone marrow biopsy in Multiple Myeloma shows plasma cells with characteristic morphology. What do plasma cells look like histologically?', '["Small lymphocytes with condensed nuclear chromatin", "Large cells with eccentric nuclei, clock-face (cartwheel) chromatin pattern, prominent perinuclear hof (pale area = Golgi apparatus), and abundant basophilic cytoplasm", "Cells with bilobed nuclei and eosinophilic granules", "Cells with multilobated nuclei and pale cytoplasm"]', 1, 'Plasma cell morphology: eccentrically placed nucleus + clock-face (cartwheel) heterochromatin + prominent perinuclear hof (pale Golgi zone where immunoglobulin is processed) + abundant basophilic cytoplasm (reflecting heavy rough ER for antibody synthesis). Flame cells = IgA myeloma (red cytoplasm from glycoprotein).'),
    (v_topic_id, 'Beta-2 microglobulin (B2M) and albumin are the two variables in the Revised International Staging System (R-ISS) for myeloma. High B2M indicates?', '["Favorable prognosis (high B2M = robust immune response)", "High tumor burden and poor prognosis — B2M is the light chain of HLA class I molecules, shed by all nucleated cells in proportion to cell turnover", "Renal function impairment only", "Anemia severity"]', 1, 'B2M is released by all nucleated cells proportional to proliferation rate. In MM, high B2M = high tumor burden = advanced stage = worse prognosis. R-ISS Stage III = B2M >5.5 mg/L + albumin <3.5 g/dL + adverse cytogenetics (del17p, t(4;14), t(14;16)) = worst prognosis.'),
    (v_topic_id, 'Thalidomide, lenalidomide, and pomalidomide are immunomodulatory drugs (IMiDs) used in myeloma. Their primary anti-myeloma mechanism is?', '["They inhibit BCR-ABL kinase", "They bind cereblon (CRL4-CRBN E3 ubiquitin ligase), causing degradation of transcription factors IKZF1 (Ikaros) and IKZF3 (Aiolos) which are critical for myeloma cell survival", "They directly induce plasma cell apoptosis via caspase 3", "They block CD20 on plasma cells"]', 1, 'IMiDs bind cereblon, redirecting the CRL4 ubiquitin ligase to tag IKZF1 and IKZF3 for proteasomal degradation. These transcription factors are essential for myeloma cell survival and IL-2 production. Loss → myeloma cell apoptosis + T-cell and NK-cell activation (immunomodulatory effects).'),
    (v_topic_id, 'Bortezomib is a proteasome inhibitor used in myeloma. What is its mechanism?', '["It inhibits the 26S proteasome, preventing degradation of key regulatory proteins including NF-kB inhibitor IkB, causing myeloma cell apoptosis", "It blocks plasma cell surface receptors", "It inhibits VEGF angiogenesis", "It activates natural killer cells directly"]', 0, 'Bortezomib inhibits the 26S proteasome, blocking intracellular protein degradation. This prevents NF-kB activation (IkB accumulates), causes ER stress (misfolded proteins accumulate), and triggers the unfolded protein response leading to apoptosis. Plasma cells are particularly vulnerable due to high secretory demand.'),
    (v_topic_id, 'AL Amyloidosis is a complication of plasma cell dyscrasias. What is deposited in tissues?', '["Whole IgG molecules", "Fibrils of misfolded immunoglobulin light chains (kappa or lambda) that deposit in organs and tissue as beta-pleated sheets", "Complement fragments", "Beta-2 microglobulin fibrils (only in dialysis amyloidosis)"]', 1, 'AL amyloidosis: light chain amyloid fibrils deposit in multiple organs. Classic organ involvement: kidney (nephrotic syndrome from glomerular deposits), heart (restrictive cardiomyopathy — most common cause of death), peripheral nerves (sensorimotor neuropathy), and macroglossia (tongue amyloid = virtually pathognomonic of AL amyloidosis).'),
    (v_topic_id, 'Congo red stain is used to diagnose amyloidosis. What does Congo red show under polarized light?', '["Red birefringence", "Apple-green birefringence under polarized light (due to the regular beta-pleated sheet structure diffracting polarized light)", "Blue birefringence", "No birefringence — amyloid is detected only on standard light microscopy"]', 1, 'Amyloid deposits stain salmon-pink with Congo red on standard microscopy. Under polarized light, the regular cross-beta structure of amyloid fibrils rotates polarized light, producing the pathognomonic apple-green birefringence. This is seen in AL, AA, ATTR, and all other amyloid types.'),
    (v_topic_id, 'Waldenstrom Macroglobulinemia is a lymphoplasmacytic lymphoma producing IgM. What is the unique clinical complication from IgM?', '["Lytic bone lesions (same as myeloma)", "Hyperviscosity syndrome: IgM pentamers are large molecules that markedly increase serum viscosity, causing blurred vision (dilated tortuous retinal veins), headache, bleeding, and neurological symptoms", "Hypocalcemia", "Autoimmune hemolytic anemia only"]', 1, 'IgM is a pentameric molecule (5 Ig units linked) — much larger than IgG. High serum IgM dramatically increases blood viscosity, causing the hyperviscosity syndrome (Bing-Neel syndrome). Unlike myeloma, Waldenstrom rarely causes lytic bone lesions. Treatment of acute hyperviscosity: plasmapheresis.'),

    -- MYELOPROLIFERATIVE NEOPLASMS (219-240)
    (v_topic_id, 'The four classic myeloproliferative neoplasms (MPNs) are defined by clonal expansion of myeloid progenitors. Which mutation is shared by Polycythemia Vera, Essential Thrombocythemia, and Primary Myelofibrosis?', '["BCR-ABL t(9;22)", "JAK2 V617F point mutation (in varying frequencies: PV >95%, ET ~50-60%, PMF ~50-60%)", "NPM1 mutation", "FLT3-ITD"]', 1, 'JAK2 V617F is the defining mutation of BCR-ABL-negative MPNs. JAK2 mediates signaling from EPO, TPO, and G-CSF receptors. V617F causes constitutive activation, driving growth-factor-independent proliferation of one or more myeloid lineages. CML is the JAK2-negative MPN (BCR-ABL driven).'),
    (v_topic_id, 'Essential Thrombocythemia (ET) is characterized by sustained platelet count >450,000/mcL. Aside from JAK2 V617F, which other mutation is common?', '["NPM1", "CALR (calreticulin) mutation in exon 9 — present in ~25-30% of ET (and ~30% of PMF), causing constitutive MPL/thrombopoietin receptor activation", "ASXL1", "TET2"]', 1, 'In JAK2 V617F-negative ET and PMF, CALR mutations are the next most common driver. Mutant calreticulin protein binds and constitutively activates the MPL (thrombopoietin receptor), mimicking TPO signaling and driving megakaryocyte proliferation.'),
    (v_topic_id, 'The major clinical complications of Essential Thrombocythemia are?', '["Infection and immunodeficiency", "Thrombosis (arterial and venous) and hemorrhage (from acquired von Willebrand disease when platelet count is extremely high)", "Respiratory failure from pulmonary infiltration", "Renal failure from platelet cast nephropathy"]', 1, 'ET complications: thrombosis (stroke, DVT/PE, MI, Budd-Chiari) from platelet activation AND bleeding (extreme thrombocytosis >1.5 million causes acquired vWD — large vWF multimers are consumed/cleaved by excess platelets). Headache and erythromelalgia (burning hands/feet from platelet-mediated microvascular occlusion) are classic symptoms.'),
    (v_topic_id, 'Primary Myelofibrosis (PMF) is characterized by progressive marrow fibrosis. What is the mechanism of fibrosis?', '["Malignant plasma cells secrete collagen directly", "Neoplastic megakaryocytes release TGF-beta and PDGF, stimulating non-clonal stromal fibroblasts to deposit reticulin and collagen fibers in the marrow", "BCR-ABL drives fibroblast activation", "Recurrent marrow infections cause scarring"]', 1, 'PMF: clonal megakaryocytes (and monocytes) release fibrogenic cytokines (TGF-beta, PDGF, bFGF) into the marrow microenvironment. These activate non-neoplastic fibroblasts to deposit reticulin (early) and collagen fibers (late), progressively replacing hematopoietic marrow.'),
    (v_topic_id, 'Leukoerythroblastosis on peripheral blood smear is characteristic of Primary Myelofibrosis. What does this term mean?', '["Elevated WBC count only", "Presence of immature WBC precursors (myelocytes, metamyelocytes) AND nucleated RBCs in peripheral blood — both pushed out of the fibrotic marrow and extramedullary hematopoiesis sites", "Smudge cells and Auer rods", "Hypersegmented neutrophils and macro-ovalocytes"]', 1, 'Leukoerythroblastosis: fibrotic marrow pushes out immature cells into blood. Smear shows: teardrop cells (dacrocytes — RBCs squeezed through fibrotic marrow), nucleated RBCs, myeloid precursors (left-shifted), and giant platelets/megakaryocyte fragments.'),
    (v_topic_id, 'Teardrop cells (dacrocytes) on peripheral smear are most classically associated with which condition?', '["Iron deficiency anemia", "Primary Myelofibrosis (fibrotic marrow deforms RBCs as they squeeze through, creating teardrop shapes pointing toward the site of hematopoiesis)", "Microangiopathic hemolytic anemia", "Thalassemia major"]', 1, 'Teardrop cells form when RBCs are physically deformed as they squeeze through fibrotic marrow sinusoids or are forced out of fibrotic tissue. The fibrosis acts like a mold, elongating the cell into a teardrop. They also appear in myelophthisic anemia (marrow replaced by tumor).'),
    (v_topic_id, 'The spleen is massively enlarged in Primary Myelofibrosis. Why?', '["Spleen traps excess platelets in ET", "Extramedullary hematopoiesis: the fibrotic marrow can no longer support blood cell production; the spleen (and liver) reactivate fetal hematopoiesis to compensate", "Splenic vein thrombosis", "CLL infiltrating the spleen"]', 1, 'In PMF, progressive marrow fibrosis destroys hematopoietic capacity. The spleen reverts to its fetal function (extramedullary hematopoiesis), becoming massively enlarged (can weigh 3-4 kg). Hepatomegaly occurs by the same mechanism. Splenomegaly causes early satiety, abdominal pain, and portal hypertension.'),
    (v_topic_id, 'Ruxolitinib is the first targeted therapy for Primary Myelofibrosis. Its mechanism is?', '["BCR-ABL inhibitor", "JAK1/JAK2 inhibitor — reduces constitutional symptoms, decreases spleen size, and improves quality of life in PMF and PV patients regardless of JAK2 V617F mutation status", "BCL2 inhibitor", "VEGF inhibitor"]', 1, 'Ruxolitinib inhibits JAK1 and JAK2, blocking cytokine signaling that drives constitutional symptoms (fever, night sweats, weight loss) and splenomegaly. It improves symptoms dramatically. However, it is not curative — allogeneic HSCT is the only cure for PMF.'),
    (v_topic_id, 'Secondary Myelofibrosis can occur after which two MPNs?', '["CML and CLL", "Post-PV myelofibrosis (from Polycythemia Vera) and post-ET myelofibrosis (from Essential Thrombocythemia) — both represent disease progression", "After aplastic anemia", "After AML remission"]', 1, 'PV and ET can both progress (transform) to secondary myelofibrosis (post-PV MF, post-ET MF) with the same clinical features as primary MF: marrow fibrosis, teardrop cells, leukoerythroblastosis, massive splenomegaly. Eventually, all three BCR-ABL-negative MPNs can transform to AML (blast crisis).'),
    (v_topic_id, 'Mast Cell Disease (Systemic Mastocytosis) is associated with mutation in which gene?', '["JAK2 V617F", "KIT D816V (activating point mutation in KIT receptor tyrosine kinase — found in >90% of systemic mastocytosis cases)", "BCR-ABL", "CALR"]', 1, 'KIT (CD117) is the stem cell factor receptor. D816V causes constitutive KIT activation, driving clonal mast cell proliferation. Symptoms: pruritus/urticaria pigmentosa (skin lesions), anaphylaxis, peptic ulcers (from histamine), bone pain/osteoporosis, and Darier sign (urtication when skin lesion is stroked).'),
    (v_topic_id, 'Langerhans Cell Histiocytosis (LCH) is characterized by clonal proliferation of Langerhans cells. What mutation is found in most cases?', '["JAK2 V617F", "BRAF V600E (present in ~60% of LCH cases)", "BCR-ABL", "NPM1"]', 1, 'BRAF V600E is the most common mutation in LCH (also found in hairy cell leukemia and melanoma). Langerhans cells are antigen-presenting cells of the epidermis. LCH can affect: bone (eosinophilic granuloma), lung, pituitary (diabetes insipidus), skin, and lymph nodes.'),
    (v_topic_id, 'Diabetes insipidus in a child with a skull lytic lesion and proptosis (bulging eye) should suggest which diagnosis?', '["Multiple myeloma", "Langerhans Cell Histiocytosis (Hand-Schuller-Christian disease: the classic triad of skull bone lesions, exophthalmos, and diabetes insipidus from pituitary/hypothalamic LCH infiltration)", "Ewing sarcoma", "Neuroblastoma"]', 1, 'Hand-Schuller-Christian disease is the chronic multisystem form of LCH (now classified as multifocal LCH). Triad: skull (punched-out lytic lesions) + exophthalmos (orbital infiltration) + diabetes insipidus (posterior pituitary/hypothalamus infiltration). This classic triad is still tested.'),
    (v_topic_id, 'Eosinophilic Granuloma is the localized form of Langerhans Cell Histiocytosis. Where does it most commonly occur?', '["Skin and lymph nodes", "Bone (especially skull, ribs, femur) — presents as painful lytic bone lesion in a child or young adult, often discovered incidentally on X-ray", "Lung exclusively", "Spleen"]', 1, 'Eosinophilic granuloma (unifocal LCH): isolated bone lesion in children/young adults. Best prognosis of all LCH forms. Skull is most common site. X-ray: punched-out lytic lesion. Biopsy shows Langerhans cells (reniform/grooved nuclei, Birbeck granules on EM, CD1a+, CD207/Langerin+, S100+) admixed with eosinophils.'),
    (v_topic_id, 'Letterer-Siwe disease is the most aggressive form of Langerhans Cell Histiocytosis. Who does it affect?', '["Elderly men (>60 years)", "Infants and young children (<2 years): presents with disseminated disease — diffuse skin rash, hepatosplenomegaly, lymphadenopathy, cytopenias — resembles sepsis and has poor prognosis", "Teenagers with bone lesions", "Adults with pulmonary involvement"]', 1, 'Letterer-Siwe disease (acute disseminated LCH): infants and toddlers with rapidly progressive multisystem LCH. Can mimic sepsis or malignancy. High mortality without chemotherapy. The skin rash is seborrheic-like (scaly, erythematous). Requires systemic chemotherapy (vinblastine + prednisone +/- BRAF inhibitor).')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
